function validate([strs]) {
  if (!Array.isArray(strs) || strs.length < 1 || strs.length > 100) return 'strs needs 1 to 100 strings.';
  for (const str of strs) {
    if (typeof str !== 'string' || str.length < 1 || str.length > 9) return 'Each string has 1 to 9 characters.';
    if (!/^[a-z0-9]+$/.test(str)) return 'Strings may contain only lowercase letters and digits.';
  }
  return null;
}

