function maximumValue(strs) {
  let best = 0;

  for (const str of strs) {
    let value = 0;
    let allDigits = true;
    for (const ch of str) {
      if (ch < '0' || ch > '9') {
        allDigits = false;
        break;
      }
      value = value * 10 + (ch.charCodeAt(0) - 48);
    }
    if (!allDigits) {
      value = str.length;
    }
    best = Math.max(best, value);
  }
  return best;
}

