function generate(rand, size) {
  const count = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const maxLength = size === 'large' ? 9 : 4;
  const digits = '0123456789', letters = 'abcdefghijklmnopqrstuvwxyz';
  const strs = [];
  for (let i = 0; i < count; i++) {
    const length = 1 + Math.floor(rand() * maxLength);
    const kind = rand();
    let str = '';
    for (let j = 0; j < length; j++) {
      // kind < 0.45: only digits (often with leading zeros); kind < 0.7: only letters; otherwise mixed.
      const useDigit = kind < 0.45 ? true : kind < 0.7 ? false : rand() < 0.5;
      const pool = useDigit ? (kind < 0.45 && rand() < 0.3 ? '0' : digits) : letters;
      str += pool[Math.floor(rand() * pool.length)];
    }
    strs.push(str);
  }
  return [strs];
}
